CREATE OR REPLACE FUNCTION custodial_coverall.bind_manual_delivery_after_acceptance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE pub uuid;binding uuid;b custodial_coverall.manual_application_bindings%rowtype;day date;a record;
BEGIN
 IF TG_TABLE_SCHEMA='public' AND TG_TABLE_NAME='static_weekly_approved_initial_confirmations' THEN
  IF NOT EXISTS(SELECT 1 FROM public.static_weekly_approved_initial_baselines baseline WHERE baseline.source_id=(NEW.receipt_json->>'source_id')::uuid
   AND baseline.feasibility#>>'{candidateSource,version,manualGroupRatingAuthority,manifestSha256}'='fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f') THEN RETURN NEW;END IF;
  pub:=NEW.publication_id;
 ELSIF TG_TABLE_SCHEMA='custodial_coverall' AND TG_TABLE_NAME='activation_receipts' THEN
  SELECT publication_id INTO STRICT pub FROM custodial_coverall.activation_progress WHERE operation_id=NEW.operation_id;
 ELSE RAISE EXCEPTION 'Exact accepted manual receipt owner required';END IF;
 binding:=custodial_coverall.bind_manual_application(pub,NULL);
 PERFORM custodial_coverall.reconcile_manual_publication(pub);
 SELECT * INTO STRICT b FROM custodial_coverall.manual_application_bindings WHERE operation_id=binding;
 FOR day IN SELECT generate_series(b.frame_start,b.frame_end,'1 day')::date LOOP
  SELECT * INTO a FROM public.static_weekly_v6_schedule_authority_state(day);
  IF a.projection_status IS DISTINCT FROM 'current' OR a.publication_id IS DISTINCT FROM pub OR a.projection_id IS NULL
   OR NOT EXISTS(SELECT 1 FROM public.weekly_schedule_lunch_documents WHERE projection_id=a.projection_id)
   THEN RAISE EXCEPTION 'New manual acceptance requires all seven exact current projection/full-lunch days in this transaction';END IF;
 END LOOP;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION custodial_coverall.reconcile_manual_delivery_after_lunch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE projection public.weekly_schedule_compiled_projections%rowtype;day date;a record;
BEGIN
 SELECT * INTO STRICT projection FROM public.weekly_schedule_compiled_projections WHERE projection_id=NEW.projection_id;
 IF EXISTS(SELECT 1 FROM custodial_coverall.manual_application_bindings WHERE publication_id=projection.publication_id) THEN
  FOR day IN SELECT generate_series(projection.week_start,projection.week_end,'1 day')::date LOOP
   SELECT * INTO a FROM public.static_weekly_v6_schedule_authority_state(day);
   IF a.projection_status='current' AND a.publication_id=projection.publication_id AND a.projection_id=projection.projection_id
    THEN PERFORM custodial_coverall.reconcile_manual_application_date(day);END IF;
  END LOOP;
 END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.custodial_sessions_preserve_original_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_employee_name text;
  v_location_code text;
  v_location_name text;
  v_device_identifier text;
  v_device_name text;
  v_assignment_epoch bigint;
begin
  if tg_op = 'INSERT' then
    select e.display_name into v_employee_name
    from public.employees e where e.id = new.employee_id;
    select l.location_code, l.location_name into v_location_code, v_location_name
    from public.locations l where l.id = new.location_id;
    select d.device_id, d.device_name, d.assignment_epoch
      into v_device_identifier, v_device_name, v_assignment_epoch
    from public.devices d where d.id = new.device_id;
    if v_employee_name is null or v_location_code is null or v_location_name is null
       or v_device_identifier is null or v_device_name is null or v_assignment_epoch is null then
      raise exception using errcode='23503', message='Cleaning identity must resolve before a session is created';
    end if;
    new.employee_name_snapshot := v_employee_name;
    new.location_code_snapshot := v_location_code;
    new.location_name_snapshot := v_location_name;
    new.device_identifier_snapshot := v_device_identifier;
    new.device_name_snapshot := v_device_name;
    new.assignment_epoch_snapshot := v_assignment_epoch;
    new.identity_snapshot_provenance := 'session_create';
    return new;
  end if;

  if row(new.id,new.session_uuid,new.client_session_id,new.employee_id,new.location_id,new.device_id,new.started_at,new.created_at)
     is distinct from
     row(old.id,old.session_uuid,old.client_session_id,old.employee_id,old.location_id,old.device_id,old.started_at,old.created_at) then
    raise exception using errcode='23514', message='Original cleaning identity is immutable; append a named-manager correction instead';
  end if;
  if row(new.employee_name_snapshot,new.location_code_snapshot,new.location_name_snapshot,
         new.device_identifier_snapshot,new.device_name_snapshot,new.assignment_epoch_snapshot,new.identity_snapshot_provenance)
     is distinct from
     row(old.employee_name_snapshot,old.location_code_snapshot,old.location_name_snapshot,
         old.device_identifier_snapshot,old.device_name_snapshot,old.assignment_epoch_snapshot,old.identity_snapshot_provenance) then
    raise exception using errcode='23514', message='At-event cleaning identity snapshots are immutable';
  end if;
  if old.finish_operation_id is not null and new.finish_operation_id is distinct from old.finish_operation_id then
    raise exception using errcode='23514', message='Cleaning finish operation identity is immutable once assigned';
  end if;
  if old.ended_at is not null and new.ended_at is distinct from old.ended_at then
    raise exception using errcode='23514', message='Cleaning end time is immutable once assigned';
  end if;
  if old.duration_minutes is not null and new.duration_minutes is distinct from old.duration_minutes then
    raise exception using errcode='23514', message='Cleaning duration is immutable once assigned';
  end if;
  if old.duration_display is not null and new.duration_display is distinct from old.duration_display then
    raise exception using errcode='23514', message='Cleaning duration display is immutable once assigned';
  end if;
  if old.completion_source is not null and new.completion_source is distinct from old.completion_source then
    raise exception using errcode='23514', message='Cleaning completion source is immutable once assigned';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_reject_retired_ops_manager_shared_thread_evidence_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_old_thread_id uuid;
  v_new_thread_id uuid;
begin
  if tg_op<>'INSERT' then v_old_thread_id:=old.thread_id; end if;
  if tg_op<>'DELETE' then v_new_thread_id:=new.thread_id; end if;
  if exists (
    select 1 from public.msg_threads t
    where t.id in (v_old_thread_id,v_new_thread_id)
      and t.system_key='ops_manager_shared_chat_v1'
  ) then
    raise exception using errcode='23514',message='The retired Operations Leadership conversation evidence is immutable';
  end if;
  return case when tg_op='DELETE' then old else new end;
end
$function$

CREATE OR REPLACE FUNCTION public.ops_manager_notification_bind_credential()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority jsonb;bound public.ops_manager_notification_credentials%rowtype;
BEGIN
 authority:=custodial_leadership_private.notification_credential(NEW.credential_id);
 IF authority IS NULL OR (TG_TABLE_NAME<>'ops_manager_notification_state'
 AND authority->>'managerId' IS DISTINCT FROM to_jsonb(NEW)->>'manager_id')
 THEN RAISE EXCEPTION 'Current typed manager notification credential required' USING ERRCODE='23514';END IF;
 INSERT INTO public.ops_manager_notification_credentials(credential_id,credential_kind,trusted_credential_id,leadership_registration_id)
 VALUES(NEW.credential_id,authority->>'kind',CASE WHEN authority->>'kind'='NAMED_TRUSTED_DEVICE' THEN NEW.credential_id ELSE NULL END,
 CASE WHEN authority->>'kind'='CUSTODIAL_LEADERSHIP_REGISTRATION' THEN NEW.credential_id ELSE NULL END)
 ON CONFLICT(credential_id) DO NOTHING;
 SELECT * INTO bound FROM public.ops_manager_notification_credentials WHERE credential_id=NEW.credential_id;
 IF bound.credential_kind IS DISTINCT FROM authority->>'kind' THEN RAISE EXCEPTION 'Notification credential domain mismatch' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sch_apply_default_coverage_purpose()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_group_code text;
  v_employee_name text;
  v_template_purpose text;
begin
  select lg.group_code into v_group_code
  from public.location_groups lg
  where lg.id = new.location_group_id;

  if new.assigned_employee_id is not null then
    select e.display_name into v_employee_name
    from public.employees e
    where e.id = new.assigned_employee_id;
  end if;

  select ct.coverage_purpose into v_template_purpose
  from public.coverage_templates ct
  where ct.location_group_id = new.location_group_id
    and ct.day_of_week = extract(dow from new.service_date)::integer
    and ct.segment_number = new.segment_number
  limit 1;

  if new.coverage_purpose is null or new.coverage_purpose = 'area_owner' then
    new.coverage_purpose := coalesce(
      v_template_purpose,
      case
        when v_group_code in ('ELEPHANT_TRUNK_GIFT_SHOP','ELEPHANT_TRUNK_RESTROOMS','BAMBOO_GIFT_SHOP','NORTH_WEST_PASSAGE_GIFT_SHOP') then 'reminder'
        when v_employee_name = 'Michael McWright' then 'late_coverage'
        when new.coverage_start < time '09:45' then 'deep_clean'
        else coalesce(new.coverage_purpose, 'area_owner')
      end
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sch_clear_scan_alerts_after_scan_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.location_code is not null then
    perform public.sch_clear_scan_alerts_for_location(new.location_code, 'new_scan_event');
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sch_guard_operational_daily_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_group_code text;
  v_day integer;
  v_employee_name text;
begin
  select group_code into v_group_code
  from public.location_groups
  where id = new.location_group_id;

  if v_group_code is null then
    raise exception 'Unknown location_group_id %', new.location_group_id;
  end if;

  v_day := extract(dow from new.service_date)::integer;

  if v_group_code like '%GIFT_SHOP' and not (
    v_day = 1
    and coalesce(new.coverage_purpose, '') = 'reminder'
    and new.coverage_start >= time '08:00'
    and new.coverage_start <= time '08:30'
    and new.coverage_end <= time '09:45'
  ) then
    select display_name into v_employee_name
    from public.employees
    where id = new.assigned_employee_id;

    raise exception 'Gift shop guard: blocked assignment for employee "%" (id %) to "%" on service_date %. Gift shops are Monday morning reminder-only side work; this assignment does not meet the reminder-only criteria.',
      coalesce(v_employee_name, 'UNKNOWN'), coalesce(new.assigned_employee_id::text, 'NULL'), v_group_code, new.service_date;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sch_guard_restricted_daily_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_day integer;
  v_group_code text;
begin
  if new.assigned_employee_id is null then
    return new;
  end if;

  -- H23: Look up group_code and fail closed on NULL.
  select group_code into v_group_code
  from public.location_groups
  where id = new.location_group_id;

  if v_group_code is null then
    raise exception 'Unknown location_group_id %', new.location_group_id;
  end if;

  v_day := extract(dow from new.service_date)::integer;

  if public.sch_is_employee_location_group_restricted(new.assigned_employee_id, new.location_group_id, v_day) then
    new.assigned_employee_id := null;
    new.owner_type := 'OPEN';
    new.status := 'OPEN';
    new.notes := trim(concat_ws(
      ' | ',
      nullif(new.notes, ''),
      'Opened by schedule safety guard: assigned employee is restricted from this location group.'
    ));
    new.source_type := trim(both ':' from concat_ws(
      ':',
      nullif(new.source_type, ''),
      'restricted_guard'
    ));
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sch_guard_restricted_location_coverage_template()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_location_group_id uuid;
begin
  if new.assigned_employee_id is null then
    return new;
  end if;

  select lgm.location_group_id
    into v_location_group_id
  from public.location_group_memberships lgm
  join public.location_groups lg on lg.id = lgm.location_group_id and lg.active = true
  where lgm.location_id = new.location_id
    and lgm.active = true
  order by lg.group_code
  limit 1;

  if v_location_group_id is not null
     and public.sch_is_employee_location_group_restricted(new.assigned_employee_id, v_location_group_id, new.day_of_week) then
    new.assigned_employee_id := null;
    new.owner_type := 'OPEN';
    new.notes := trim(concat_ws(
      ' | ',
      nullif(new.notes, ''),
      'Opened by schedule safety guard: assigned employee is restricted from this location group.'
    ));
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sch_pto_absence_sync_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_start date;
  v_end date;
begin
  if tg_op = 'DELETE' then
    v_start := old.start_date;
    v_end := old.end_date;
  elsif tg_op = 'INSERT' then
    v_start := new.start_date;
    v_end := new.end_date;
  else
    v_start := least(coalesce(old.start_date, new.start_date), coalesce(new.start_date, old.start_date));
    v_end := greatest(coalesce(old.end_date, new.end_date), coalesce(new.end_date, old.end_date));
  end if;

  perform public.sch_sync_pto_absence_overrides(v_start, v_end);
  perform public.sch_regenerate_existing_schedules_for_absence_range(v_start, v_end);
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_component_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_state text;
begin
  select lifecycle_state into v_state from public.weekly_schedule_versions where version_id=coalesce(new.version_id,old.version_id);
  if current_setting('app.static_weekly_draft_write',true)='on' and v_state='draft' then
    if tg_op='DELETE' then return old; end if; return new;
  end if;
  if current_setting('app.static_weekly_publish_write',true)='on' and v_state='published' and tg_op='INSERT' then return new; end if;
  raise exception using errcode='23514',message='scheduler components may change only through a revision-checked v2 command';
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v15_advance_recurring_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_table_name='employees' then
    if tg_op='UPDATE' and new.active is not distinct from old.active
      and new.display_name is not distinct from old.display_name
      and new.employee_code is not distinct from old.employee_code then return null;end if;
    if tg_op='INSERT' and new.employee_code!~'^EMP[0-9]+$' and not exists(select 1 from public.weekly_roster_slot_incumbencies i where i.person_id=new.id) then return null;end if;
    if tg_op='DELETE' and old.employee_code!~'^EMP[0-9]+$' and not exists(select 1 from public.weekly_roster_slot_incumbencies i where i.person_id=old.id) then return null;end if;
    if tg_op='UPDATE' and new.employee_code!~'^EMP[0-9]+$' and old.employee_code!~'^EMP[0-9]+$' and not exists(select 1 from public.weekly_roster_slot_incumbencies i where i.person_id=new.id) then return null;end if;
  elsif tg_table_name='static_weekly_authority_source_documents' then
    -- Registration is immutable evidence, not schedule activation. Retirement
    -- or corruption/change of a selected source does invalidate preview basis.
    if tg_op='INSERT' then return null;end if;
    if tg_op='UPDATE' and new.active is not distinct from old.active
      and new.retired_at is not distinct from old.retired_at
      and new.canonical_source is not distinct from old.canonical_source
      and new.source_digest is not distinct from old.source_digest then return null;end if;
  elsif tg_op='UPDATE' and to_jsonb(new)=to_jsonb(old) then return null;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  update public.static_weekly_recurring_generation set generation=generation+1,
    changed_at=statement_timestamp() where singleton;
  if not found then raise exception 'recurring generation singleton is missing';end if;

  perform public.static_weekly_v21_track_dependency_change(tg_table_name,tg_op,
   case when tg_op='INSERT' then null else to_jsonb(old) end,
   case when tg_op='DELETE' then null else to_jsonb(new) end);

  return null;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare source_comparison public.weekly_schedule_versions%rowtype;
begin
  if tg_op='DELETE' then raise exception using errcode='23514',message='weekly versions are immutable'; end if;
  if tg_op='INSERT' then
    if new.lifecycle_state='published' and current_setting('app.static_weekly_publish_write',true) is distinct from 'on' then raise exception using errcode='23514',message='published versions require v2 publication'; end if;
    return new;
  end if;
  if old.lifecycle_state='draft' and current_setting('app.static_weekly_publish_write',true)='on' and new.lifecycle_state='published' and new.revision=old.revision then return new; end if;
  -- v3 binds a just-created v2 draft to a registered immutable source inside
  -- the same SECURITY DEFINER transaction. No other field/revision may move.
  if old.lifecycle_state='draft' and current_setting('app.static_weekly_source_bind',true)='on' and old.authority_source_id is null and new.authority_source_id is not null then
    source_comparison:=new;
    source_comparison.authority_source_id:=old.authority_source_id;
    if source_comparison is not distinct from old then return new; end if;
  end if;
  if old.lifecycle_state<>'draft' or current_setting('app.static_weekly_draft_write',true) is distinct from 'on' or new.lifecycle_state<>'draft' or new.revision<>old.revision+1 then raise exception using errcode='23514',message='draft versions require a revision-checked v2 command'; end if;
  return new;
end
$function$
